// Read incoming lead (webhook body). Accept url or final_url.
const body = $input.first().json.body || $input.first().json || {};
let url = (body.final_url || body.url || body.website_url || body.website || '').toString().trim();
const leadId = body.lead_id || body.leadId || null;
const businessName = body.business_name || body.businessName || null;

// URL normalization: ensure a scheme, default to https
if (url && !/^https?:\/\//i.test(url)) {
  url = 'https://' + url;
}

// Configurable thresholds & category weights (edit here — never hardcoded in the report node).
const config = {
  thresholds: {
    lcp_ms: 2500,          // Largest Contentful Paint target < 2.5s
    cls: 0.1,              // Cumulative Layout Shift target < 0.1
    tbt_ms: 200,           // Total Blocking Time target < 200ms
    speed_index_ms: 3400,  // Speed Index target < 3.4s
    fcp_ms: 1800,          // First Contentful Paint target < 1.8s
    tti_ms: 3800,          // Time to Interactive target < 3.8s
    total_byte_weight: 1600000, // Page weight target < ~1.6MB
    request_count: 50,     // Requests target < 50
  },
  // Blend used to derive the single performance_score (mobile is weighted higher — mobile-first).
  perf_blend: { mobile: 0.6, desktop: 0.4 },
};

return [{ json: { lead_id: leadId, business_name: businessName, url: url || null, valid_url: !!url, config } }];

const nowIso = new Date().toISOString();
// Point to the Run Website Audit node
const prep = $('Run Website Audit').first().json;
const config = prep.config;
const t = config.thresholds;

const mobileRes = $('PSI Mobile').first().json || {};
const desktopRes = $('PSI Desktop').first().json || {};

// ---- Audit-error detection ----
function extractLH(res) {
  if (res && res.lighthouseResult) return res.lighthouseResult;
  return null;
}
const lhMobile = extractLH(mobileRes);
const lhDesktop = extractLH(desktopRes);

const auditErrors = [];
if (mobileRes && mobileRes.error) auditErrors.push('mobile: ' + (mobileRes.error.message || 'PSI error'));
if (desktopRes && desktopRes.error) auditErrors.push('desktop: ' + (desktopRes.error.message || 'PSI error'));
if (!prep.valid_url) auditErrors.push('No valid URL supplied');

// If we have no lighthouse data at all -> inconclusive
if (!lhMobile && !lhDesktop) {
  return [{
    json: {
      lead_id: prep.lead_id,
      business_name: prep.business_name,
      final_url: prep.final_url,
      platform: "Inconclusive",
      audit_date: nowIso,
      audit_status: 'inconclusive',
      manual_review_required: true,
      performance_score: null,
      technical_score: null,
      accessibility_score: null,
      seo_score: null,
      design_score: null,
      conversion_score: null,
      overall_score: null,
      classification: "INCONCLUSIVE",
      top_5_problems: [],
      performance_findings: [],
      technical_findings: [],
      metrics: {},
      audit_error: auditErrors.join('; ') || 'PageSpeed Insights returned no Lighthouse result',
      retry_count: 0,
      tool_versions: { pagespeed_insights: 'v5' },
      audit_started_at: nowIso,
      audit_completed_at: nowIso,
    },
  }];
}

const primary = lhMobile || lhDesktop;
function num(lh, id) {
  const a = lh && lh.audits && lh.audits[id];
  return a && typeof a.numericValue === 'number' ? a.numericValue : null;
}
function auditScore(lh, id) {
  const a = lh && lh.audits && lh.audits[id];
  return a && typeof a.score === 'number' ? a.score : null;
}
function catScore(lh, id) {
  const c = lh && lh.categories && lh.categories[id];
  return c && typeof c.score === 'number' ? c.score : null;
}
function requests(lh) {
  const a = lh && lh.audits && lh.audits['network-requests'];
  const items = a && a.details && a.details.items;
  return Array.isArray(items) ? items.length : null;
}

// ---- Core metrics ----
const metrics = {
  mobile: {
    performance: catScore(lhMobile, 'performance'),
    best_practices: catScore(lhMobile, 'best-practices'),
    lcp_ms: num(lhMobile, 'largest-contentful-paint'),
    cls: num(lhMobile, 'cumulative-layout-shift'),
    tbt_ms: num(lhMobile, 'total-blocking-time'),
    speed_index_ms: num(lhMobile, 'speed-index'),
    fcp_ms: num(lhMobile, 'first-contentful-paint'),
    tti_ms: num(lhMobile, 'interactive'),
    total_byte_weight: num(lhMobile, 'total-byte-weight'),
    request_count: requests(lhMobile),
    viewport_ok: auditScore(lhMobile, 'viewport') === 1,
    content_width_ok: auditScore(lhMobile, 'content-width') === 1,
    is_https: auditScore(lhMobile, 'is-on-https') === 1,
  },
  desktop: {
    performance: catScore(lhDesktop, 'performance'),
    best_practices: catScore(lhDesktop, 'best-practices'),
    lcp_ms: num(lhDesktop, 'largest-contentful-paint'),
    cls: num(lhDesktop, 'cumulative-layout-shift'),
    tbt_ms: num(lhDesktop, 'total-blocking-time'),
    speed_index_ms: num(lhDesktop, 'speed-index'),
    total_byte_weight: num(lhDesktop, 'total-byte-weight'),
    request_count: requests(lhDesktop),
  },
};

// ---- Evidence-backed findings helper ----
const perfFindings = [];
const techFindings = [];
function fmtSec(ms) { return ms == null ? 'n/a' : (ms / 1000).toFixed(1) + ' s'; }
function fmtMs(ms) { return ms == null ? 'n/a' : Math.round(ms) + ' ms'; }
function fmtKb(b) { return b == null ? 'n/a' : Math.round(b / 1024) + ' KB'; }

function addPerf(test, observed, expected, ok, severity, source, rec) {
  if (ok) return;
  perfFindings.push({ category: 'Performance', test, observed_value: observed, expected_threshold: expected, severity, evidence_source: source, recommendation: rec });
}
function addTech(test, observed, expected, ok, severity, source, rec) {
  if (ok) return;
  techFindings.push({ category: 'Technical Health', test, observed_value: observed, expected_threshold: expected, severity, evidence_source: source, recommendation: rec });
}

const m = metrics.mobile;
// Performance findings
addPerf('Mobile LCP', fmtSec(m.lcp_ms), 'Target below ' + fmtSec(t.lcp_ms), m.lcp_ms == null || m.lcp_ms <= t.lcp_ms, m.lcp_ms > t.lcp_ms * 2 ? 'High' : 'Medium', 'Lighthouse mobile audit', 'Optimize images, reduce render-blocking resources and improve page delivery');
addPerf('Cumulative Layout Shift', m.cls == null ? 'n/a' : m.cls.toFixed(2), 'Target below ' + t.cls, m.cls == null || m.cls <= t.cls, m.cls > t.cls * 2 ? 'High' : 'Medium', 'Lighthouse mobile audit', 'Set explicit width/height on media and reserve space for dynamic content');
addPerf('Total Blocking Time', fmtMs(m.tbt_ms), 'Target below ' + fmtMs(t.tbt_ms), m.tbt_ms == null || m.tbt_ms <= t.tbt_ms, m.tbt_ms > t.tbt_ms * 3 ? 'High' : 'Medium', 'Lighthouse mobile audit', 'Reduce and defer JavaScript, split long tasks');
addPerf('Speed Index', fmtSec(m.speed_index_ms), 'Target below ' + fmtSec(t.speed_index_ms), m.speed_index_ms == null || m.speed_index_ms <= t.speed_index_ms, 'Medium', 'Lighthouse mobile audit', 'Improve above-the-fold render speed and prioritize visible content');
addPerf('Time to Interactive', fmtSec(m.tti_ms), 'Target below ' + fmtSec(t.tti_ms), m.tti_ms == null || m.tti_ms <= t.tti_ms, 'Medium', 'Lighthouse mobile audit', 'Reduce main-thread work and third-party script cost');

// Page weight / resource findings
addPerf('Total Page Weight', fmtKb(m.total_byte_weight), 'Target below ' + fmtKb(t.total_byte_weight), m.total_byte_weight == null || m.total_byte_weight <= t.total_byte_weight, m.total_byte_weight > t.total_byte_weight * 2 ? 'High' : 'Medium', 'Lighthouse network audit', 'Compress assets, remove unused code and lazy-load below-the-fold media');
addPerf('Request Count', m.request_count == null ? 'n/a' : String(m.request_count) + ' requests', 'Target below ' + t.request_count, m.request_count == null || m.request_count <= t.request_count, 'Medium', 'Lighthouse network audit', 'Bundle assets and reduce the number of network requests');

// Image optimization findings
const optImg = auditScore(primary, 'uses-optimized-images');
const modImg = auditScore(primary, 'modern-image-formats');
const respImg = auditScore(primary, 'uses-responsive-images');
addPerf('Image Optimization', optImg === 1 ? 'Optimized' : 'Unoptimized images detected', 'Images efficiently encoded', optImg == null || optImg === 1, 'Medium', 'Lighthouse audit (uses-optimized-images)', 'Compress and properly encode images to reduce transfer size');
addPerf('Modern Image Formats', modImg === 1 ? 'Modern formats used' : 'Legacy image formats detected', 'Serve WebP/AVIF where supported', modImg == null || modImg === 1, 'Low', 'Lighthouse audit (modern-image-formats)', 'Serve images in next-gen formats such as WebP or AVIF');
addPerf('Responsive Images', respImg === 1 ? 'Appropriately sized' : 'Oversized images served', 'Serve appropriately sized images', respImg == null || respImg === 1, 'Low', 'Lighthouse audit (uses-responsive-images)', 'Serve images sized for the device viewport');

// Mobile usability findings
addPerf('Mobile Viewport', m.viewport_ok ? 'Configured' : 'Missing/invalid viewport', 'Responsive viewport meta present', m.viewport_ok, 'High', 'Lighthouse mobile audit (viewport)', 'Add a responsive viewport meta tag');
addPerf('Content Width (horizontal overflow)', m.content_width_ok ? 'Fits viewport' : 'Content wider than screen', 'Content sized to viewport', m.content_width_ok, 'Medium', 'Lighthouse mobile audit (content-width)', 'Fix layout so content does not overflow horizontally on mobile');

// ---- Technical health findings ----
const httpsOk = m.is_https || auditScore(lhDesktop, 'is-on-https') === 1;
addTech('HTTPS', httpsOk ? 'Enabled' : 'Not served over HTTPS', 'Site served over HTTPS', httpsOk, 'High', 'Lighthouse audit (is-on-https)', 'Install a valid TLS certificate and force HTTPS redirects');
const consoleOk = auditScore(primary, 'errors-in-console');
addTech('Console Errors', consoleOk === 1 ? 'None' : 'Console errors logged', 'No browser console errors', consoleOk == null || consoleOk === 1, 'Medium', 'Lighthouse audit (errors-in-console)', 'Fix JavaScript errors reported in the browser console');
const compOk = auditScore(primary, 'uses-text-compression');
addTech('Text Compression', compOk === 1 ? 'Enabled' : 'Uncompressed text assets', 'Gzip/Brotli enabled', compOk == null || compOk === 1, 'Low', 'Lighthouse audit (uses-text-compression)', 'Enable Gzip or Brotli compression for text assets');
const bpMobile = metrics.mobile.best_practices;
addTech('Best Practices Score', bpMobile == null ? 'n/a' : Math.round(bpMobile * 100) + '/100', 'Target 90+/100', bpMobile == null || bpMobile >= 0.9, bpMobile != null && bpMobile < 0.7 ? 'High' : 'Medium', 'Lighthouse best-practices category', 'Address flagged best-practice issues (security, deprecations, errors)');



/// Function to calculate score directly from Lighthouse Audits or Numeric Values
function calculatePerfFromAudits(lh) {
  if (!lh || !lh.audits) return null;

  // 1. Pehle Try Karein Direct Score Property (0 se 1)
  const lcpScore = lh.audits['largest-contentful-paint']?.score;
  const tbtScore = lh.audits['total-blocking-time']?.score;
  const clsScore = lh.audits['cumulative-layout-shift']?.score;
  const speedIndexScore = lh.audits['speed-index']?.score;
  const fcpScore = lh.audits['first-contentful-paint']?.score;

  const validScores = [lcpScore, tbtScore, clsScore, speedIndexScore, fcpScore].filter(
    (s) => typeof s === 'number'
  );

  if (validScores.length > 0) {
    return validScores.reduce((a, b) => a + b, 0) / validScores.length;
  }

  // 2. Fallback: Agar score null ho, toh numericValue (ms/unit) se score Estimate karein
  const lcpMs = lh.audits['largest-contentful-paint']?.numericValue;
  const tbtMs = lh.audits['total-blocking-time']?.numericValue;
  const cls = lh.audits['cumulative-layout-shift']?.numericValue;

  let estimatedScores = [];

  if (typeof lcpMs === 'number') {
    // LCP <= 2500ms (Good = 1.0), >= 4000ms (Poor = 0.3)
    estimatedScores.push(lcpMs <= 2500 ? 0.95 : lcpMs <= 4000 ? 0.65 : 0.25);
  }
  if (typeof tbtMs === 'number') {
    // TBT <= 200ms (Good = 1.0), >= 600ms (Poor = 0.3)
    estimatedScores.push(tbtMs <= 200 ? 0.95 : tbtMs <= 600 ? 0.65 : 0.25);
  }
  if (typeof cls === 'number') {
    // CLS <= 0.1 (Good = 1.0), >= 0.25 (Poor = 0.3)
    estimatedScores.push(cls <= 0.1 ? 0.95 : cls <= 0.25 ? 0.65 : 0.25);
  }

  if (estimatedScores.length > 0) {
    return estimatedScores.reduce((a, b) => a + b, 0) / estimatedScores.length;
  }

  return null;
}

// 1. Pehle Direct Category Score Check Karein
let pmRaw = lhMobile?.categories?.performance?.score ?? null;
let pdRaw = lhDesktop?.categories?.performance?.score ?? null;

// 2. Agar Category Score NULL ho, toh Audits se Calculate Karein
if (pmRaw === null) pmRaw = calculatePerfFromAudits(lhMobile);
if (pdRaw === null) pdRaw = calculatePerfFromAudits(lhDesktop);

// 3. Last Line Fallback: Agar phir bhi NULL ho, toh baki accurate scores ka average lein
let performance_score= null;

if (pmRaw !== null && pdRaw !== null) {
  performance_score = Math.round((pmRaw * 0.6 + pdRaw * 0.4) * 100);
} else if (pmRaw !== null) {
  performance_score = Math.round(pmRaw * 100);
} else if (pdRaw !== null) {
  performance_score = Math.round(pdRaw * 100);
} else {
  // Hard Fallback: Technical aur SEO score ka weighted estimate agar PSI Performance poori tarah drop karde


}
// Technical health score: blend of best-practices + HTTPS/console/compression signals.
const techSignals = [];
if (bpMobile != null) techSignals.push(bpMobile);
techSignals.push(httpsOk ? 1 : 0);
if (consoleOk != null) techSignals.push(consoleOk);
if (compOk != null) techSignals.push(compOk);
let technical_score = techSignals.length
  ? Math.round((techSignals.reduce((a, b) => a + b, 0) / techSignals.length) * 100)
  : null;

// ==========================================
// SCORING & LOGIC UPDATES
// ==========================================

const accessibility_score = catScore(primary, 'accessibility') != null 
  ? Math.round(catScore(primary, 'accessibility') * 100) 
  : null;

const seo_score = catScore(primary, 'seo') != null 
  ? Math.round(catScore(primary, 'seo') * 100) 
  : null;

function getPlatform(lh) {
  const lib = lh && lh.audits && lh.audits['detected-javascript-libraries'];
  const items = lib && lib.details && lib.details.items;
  if (Array.isArray(items) && items.length > 0) {
    return items.map(i => i.name).join(', ');
  }
  return 'Custom / Unknown';
}
const platform = getPlatform(primary);

let design_score = 100;
if (!metrics.mobile.viewport_ok) design_score -= 40;
if (!metrics.mobile.content_width_ok) design_score -= 30;
if (metrics.mobile.cls > 0.25) design_score -= 20;
if (design_score < 0) design_score = 0;

let conversion_score = Math.round(((performance_score || 50) + (httpsOk ? 100 : 0)) / 2);

const scores = [performance_score, technical_score, accessibility_score, seo_score, design_score, conversion_score].filter(v => v != null);

if (scores.length > 0) {
    performance_score = Math.round(scores.reduce((a, b) => a + b, 0) / scores.length);
  }

const overall_score = scores.length ? Math.round(scores.reduce((a, b) => a + b, 0) / scores.length) : null;

let classification = 'POOR / CRITICAL';
if (overall_score >= 80) classification = 'GOOD';
else if (overall_score >= 60) classification = 'NEEDS IMPROVEMENT';

const allFindings = [...perfFindings, ...techFindings];
allFindings.sort((a, b) => (a.severity === 'High' ? -1 : 1));
const top_5_problems = allFindings.slice(0, 5).map(f => `${f.test}: ${f.observed_value} (${f.recommendation})`);
const audit_status = auditErrors.length && (!lhMobile || !lhDesktop) ? 'partial' : 'success';

return [{
  json: {
    lead_id: prep.lead_id,
    business_name: prep.business_name,
    final_url: prep.final_url,
    platform,
    audit_date: nowIso,
    audit_status,
    performance_score,
    technical_score,
    accessibility_score,
    seo_score,
    design_score,
    conversion_score,
    overall_score,
    classification,
    top_5_problems,
    metrics,
    performance_findings: perfFindings,
    technical_findings: techFindings,
    findings_count: perfFindings.length + techFindings.length,
    manual_review_required: audit_status !== 'success',
    audit_error: auditErrors.join('; ') || null,
    retry_count: 0,
    tool_versions: {
      pagespeed_insights: 'v5',
      lighthouse: (primary && primary.lighthouseVersion) || null,
    },
    thresholds_used: t,
    audit_started_at: nowIso,
    audit_completed_at: nowIso,
  },
}];

// Loop through all incoming website items from the Google Sheet
for (const item of $input.all()) {
  let rawUrl = item.json.url || "";

  // 1. URL Normalization (Adds https:// if missing and cleans spaces)
  let cleanUrl = rawUrl.trim();
  if (cleanUrl && !/^https?:\/\//i.test(cleanUrl)) {
    cleanUrl = 'https://' + cleanUrl;
  }

  // 2. Set default parameters for the rest of the team
  item.json.original_website_url = rawUrl;
  item.json.final_url = cleanUrl;
  item.json.audit_status = "Reachable";

  // Note: Since standard JavaScript inside cloud n8n cannot launch a local browser,
  // we use a standard placeholder name for the screenshot.
  item.json.screenshot_url = "website_screenshot.png";
  item.json.audit_error = null;
}

// Pass the updated data down the line to Fatima and Furqan
return $input.all();

// Get input data from the previous node
const inputData = $input.first().json;
const url = inputData.url || inputData.business_url;

if (!url) {
  throw new Error("No URL available to process.");
}

let html = "";
try {
  // Use n8n's internal httpRequest helper to fetch live website HTML safely
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: url,
    returnFullResponse: true,
    headers: {
      'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
      'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8'
    }
  });

  // Extract body content from response
  html = typeof response.body === 'string' ? response.body : JSON.stringify(response.body);
} catch (error) {
  html = "";
}

// Parse real metadata elements from live HTML
const titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i);
const title = titleMatch ? titleMatch[1].trim() : null;

const metaDescMatch = html.match(/<meta\s+name=["']description["']\s+content=["']([^"']+)["']/i);
const metaDescription = metaDescMatch ? metaDescMatch[1].trim() : null;

const h1Matches = html.match(/<h1[^>]*>.*?<\/h1>/gis);
const h1Count = h1Matches ? h1Matches.length : 0;

const hasLocalBusinessSchema = /["']@type["']\s*:\s*["'](LocalBusiness|Organization|Store|Restaurant|Place)["']/i.test(html);

// Parse real accessibility elements (image alt tags)
const imgTags = html.match(/<img[^>]*>/gis) || [];
let missingAltCount = 0;
imgTags.forEach(img => {
  if (!/alt\s*=\s*["'][^"']+["']/i.test(img)) {
    missingAltCount++;
  }
});

// Calculate real audit scores
let seoScore = 100;
if (!title) seoScore -= 35;
if (!metaDescription) seoScore -= 35;
if (h1Count === 0) seoScore -= 30;

let accessibilityScore = 100;
if (imgTags.length > 0) {
  accessibilityScore = Math.max(0, Math.round(100 - ((missingAltCount / imgTags.length) * 100)));
}

return [{
  json: {
    lead_id: inputData.lead_id || "LEAD-101",
    business_name: inputData.business_name || "Unknown Business",
    url: url,
    seo_local: {
      title: title,
      meta_description: metaDescription,
      h1_count: h1Count,
      has_local_business_schema: hasLocalBusinessSchema
    },
    accessibility: {
      total_images: imgTags.length,
      images_missing_alt: missingAltCount
    },
    seo_score: Math.max(0, seoScore),
    accessibility_score: accessibilityScore,
    audit_status: html ? "Parsed live page data" : "Blocked or failed to fetch live URL"
  }
}];
